```cpp
#include <iostream>
using namespace std;

// Node definition
class Node {
public:
    int data;
    Node* next;

    Node(int val) {
        data = val;
        next = NULL;
    }
};

// Global head pointer for linked list
Node* head = NULL;

// Function to display list
void display() {
    if (head == NULL) {
        cout << "List is empty!" << endl;
        return;
    }
    Node* temp = head;
    cout << "Linked List: ";
    while (temp != NULL) {
        cout << temp->data << " -> ";
        temp = temp->next;
    }
    cout << "NULL" << endl;
}

// Insert at Nth position
void insertAtPosition(int val, int pos) {
    Node* newNode = new Node(val);

    if (pos == 1) { // Insert at head
        newNode->next = head;
        head = newNode;
        return;
    }

    Node* temp = head;
    for (int i = 1; i < pos - 1 && temp != NULL; i++) {
        temp = temp->next;
    }

    if (temp == NULL) {
        cout << "Position out of range!" << endl;
        delete newNode;
        return;
    }

    newNode->next = temp->next;
    temp->next = newNode;
}

// Menu function
void menu() {
    int choice, val, pos;
    while (true) {
        cout << "\n===== Linked List Menu =====" << endl;
        cout << "1. Display" << endl;
        cout << "2. Insert at Nth Position" << endl;
        cout << "3. Exit" << endl;
        cout << "Enter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                display();
                break;
            case 2:
                cout << "Enter value: ";
                cin >> val;
                cout << "Enter position: ";
                cin >> pos;
                insertAtPosition(val, pos);
                break;
            case 3:
                cout << "Exiting program." << endl;
                return;
            default:
                cout << "Invalid choice! Try again." << endl;
        }
    }
}

// Main function
int main() {
    menu();
    return 0;
}
```

